import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.plugin.java.JavaPlugin;
public class Probe extends JavaPlugin {
 public void onEnable(){getServer().getScheduler().runTaskLater(this,()->{boolean ok=true;World w=Bukkit.getWorld("hylor_prison");if(w==null){ok=false;}else{if(w.getBlockAt(0,82,0).getType()!=Material.MAGENTA_GLAZED_TERRACOTTA)ok=false;if(w.getBlockAt(-13,97,-18).getType()!=Material.PINK_CONCRETE){getLogger().severe("Missing logo");ok=false;}try(var stream=new java.net.URL("http://127.0.0.1:8765/hylor.zip").openStream()){if(stream.read()!=0x50||stream.read()!=0x4b)ok=false;}catch(Exception ex){getLogger().severe("Pack endpoint: "+ex);ok=false;}for(int i=0;i<5;i++){Material m=w.getBlockAt(i*80,80,120).getType();if(m==Material.AIR||m==Material.BEDROCK)ok=false;}int[][] points={{-12,-11},{-4,-11},{4,-11},{12,-11},{0,13}};java.util.Set<String> seen=new java.util.HashSet<>();long count=0;for(int[] pt:points){int cx=pt[0]>>4,cz=pt[1]>>4;if(seen.add(cx+":"+cz))for(Entity e:w.getChunkAt(cx,cz).getEntities())if(e instanceof Villager && e.getCustomName()!=null)count++;}if(count!=5){getLogger().severe("NPC count="+count);ok=false;}}for(String c:new String[]{"spawn","mines","shop","auto","quests","evo","balance","kit"})if(Bukkit.getPluginCommand(c)==null){getLogger().severe("Missing command "+c);ok=false;}getLogger().info("HYLOR_INTEGRATION_CHECK="+(ok?"PASS":"FAIL"));Bukkit.shutdown();},80);}
}
